function contentKey(){const item=page==='replies'?state.snippets.find(s=>s.id===selected):clipsByID.get(selected);return JSON.stringify([page,selected,selectedQueueIndex,query,item&&('hash'in item?[item.hash,item.kind]:[item.revision,item.kind])]);}
function suspendDetail(){const root=q('detail');if(root?.childElementCount){const key=contentKey(),reader=disposeTextPreview?.snapshot();if(reader||!suspendedPreview||suspendedPreview.key!==key)suspendedPreview={key,top:root.querySelector('.preview-body')?.scrollTop||0,left:root.querySelector('.preview-body')?.scrollLeft||0,reader};}releaseDetail();root?.replaceChildren();}
function releaseDetail(){if(detailRoot)clearMarkup(detailRoot);renderedPreviewIdentity='';retainedClip=undefined;pendingPreview=undefined;if(imageLease){void api.releasePreview(imageLease).catch(()=>{});imageLease=undefined;}disposeTextPreview?.();disposeTextPreview=undefined;disposeImagePreview?.();disposeImagePreview=undefined;disposeFilesPreview?.();disposeFilesPreview=undefined;detailKey='';detailRoot=undefined;detailToken++;}
function currentDetailKey(){const item=page==='replies'?state.snippets.find(s=>s.id===selected):clipsByID.get(selected);const metadata=item&&('hash'in item?[item.id,item.hash,item.kind,item.title,item.source,item.createdAt,item.updatedAt,item.favorite,item.pinned,item.tags,item.bytes,item.shared,item.localOnly]:[item.id,item.title,item.updatedAt,item.kind,item.shortcut,item.revision]);return JSON.stringify([page,selected,selectedQueueIndex,query,state.queue.includes(selected),state.stack.options.duplicates,metadata]);}
function showTextReader(text:string,code:boolean){const host=q('detail').querySelector<HTMLElement>('.preview-body')!,button=q<HTMLButtonElement>('preview-wrap'),storageKey=code?'preview-code-wrap':'preview-text-wrap',saved=localStorage.getItem(storageKey);disposeTextPreview=mountTextPreview(host,text,{code,query,wrap:saved===null?!code:saved==='true',wrapButton:button,changedWrap:value=>localStorage.setItem(storageKey,String(value)),resume:suspendedPreview?.key===contentKey()?suspendedPreview.reader:undefined});}
