function manageCategories(){
 const order=state.categories.map(category=>category.id);
 modal(tr('管理分类'),`<p class="category-order-help">${tr('拖动分类调整顺序，也可以使用 Alt + 方向键。')}</p><div id="category-order-list" class="category-order-list"></div>`,async()=>{await api.reorderCategories(order);await refresh();toast(tr('分类顺序已保存'));},tr('完成'));
 const root=q('category-order-list');root.innerHTML=order.map(id=>{const category=state.categories.find(item=>item.id===id)!;return `<div class="category-order-row" data-category-order="${id}"><span class="category-order-grip" draggable="true" tabindex="0" aria-label="${esc(tr('拖拽排序')+' · '+category.name)}" title="${tr('拖拽排序')}">${ico('grip')}</span><span class="category-mark" style="--category-color:${category.color}">${categoryGlyph(category.icon)}</span><span class="category-order-name">${esc(category.name)}</span></div>`;}).join('');hydrateCategoryGlyphs(root);
 bindSortable(root,{itemSelector:'.category-order-row',handleSelector:'.category-order-grip',id:item=>item.dataset.categoryOrder!,commit:ids=>{order.splice(0,order.length,...ids);}});
}
function manageSidebar(){
  const draft=readSidebarLayout();
  const groupNames:Record<SidebarGroup,string>={clipboard:tr('剪贴板'),tools:tr('工具'),connections:tr('连接与分享')};
  const iconNames:Record<string,string>={shelf:'files',favorites:'star',stack:'stack',replies:'replies',history:'history','text-tools':'bot','capture-tools':'monitor',ai:'bot',scripts:'code',symbols:'smile',cheats:'book',sync:'devices',web:'monitor',uri:'link'};
  const draw=()=>{
    const root=q('sidebar-order-list');
    root.innerHTML=(Object.keys(sidebarGroups) as SidebarGroup[]).map(group=>`<section class="sidebar-manage-group" data-manage-group="${group}"><h3>${groupNames[group]}</h3>${draft.order[group].map(key=>`<div class="sidebar-manage-row" data-sidebar-key="${key}" data-sidebar-group="${group}"><button type="button" class="sidebar-manage-grip" draggable="true" aria-label="${esc(labels[key])} · ${tr('拖拽排序')}" aria-keyshortcuts="Alt+ArrowUp Alt+ArrowDown" title="${tr('拖拽排序')}">${ico('grip')}</button><span class="sidebar-manage-icon">${ico(iconNames[key])}</span><span class="sidebar-manage-label">${esc(labels[key])}</span><label class="sidebar-manage-visible"><input type="checkbox" data-sidebar-visible="${key}" ${draft.hidden.includes(key)?'':'checked'}><span>${tr('显示')}</span></label></div>`).join('')}</section>`).join('')+`<label class="sidebar-manage-categories"><input type="checkbox" id="sidebar-categories-visible" ${draft.categoriesVisible?'checked':''}><span>${tr('显示自定义分类')}</span></label>`;
    root.querySelectorAll<HTMLInputElement>('[data-sidebar-visible]').forEach(input=>input.onchange=()=>{
      draft.hidden=input.checked?draft.hidden.filter(key=>key!==input.dataset.sidebarVisible):[...draft.hidden,input.dataset.sidebarVisible!];
    });
    q<HTMLInputElement>('sidebar-categories-visible').onchange=event=>{
      draft.categoriesVisible=(event.currentTarget as HTMLInputElement).checked;
    };
    root.querySelectorAll<HTMLButtonElement>('.sidebar-manage-grip').forEach(grip=>{
      grip.onkeydown=event=>{
        if(!event.altKey||(event.key!=='ArrowUp'&&event.key!=='ArrowDown'))return;
        event.preventDefault();
        const row=grip.closest<HTMLElement>('.sidebar-manage-row')!;
        const group=row.dataset.sidebarGroup as SidebarGroup,key=row.dataset.sidebarKey!;
        const order=draft.order[group],index=order.indexOf(key),next=index+(event.key==='ArrowUp'?-1:1);
        if(next<0||next>=order.length)return;
        [order[index],order[next]]=[order[next],order[index]];
        draw();
        root.querySelector<HTMLButtonElement>(`[data-sidebar-key="${key}"] .sidebar-manage-grip`)?.focus();
      };
    });
    root.querySelectorAll<HTMLElement>('.sidebar-manage-group').forEach(groupNode=>{const group=groupNode.dataset.manageGroup as SidebarGroup;bindSortable(groupNode,{itemSelector:'.sidebar-manage-row',handleSelector:'.sidebar-manage-grip',id:item=>item.dataset.sidebarKey!,commit:ids=>{draft.order[group].splice(0,draft.order[group].length,...ids);}});});
  };
  modal(tr('管理侧边栏'),'<div id="sidebar-order-list" class="sidebar-order-list"></div>',async()=>{
    saveSidebarLayout(draft);
    toast(tr('侧边栏已更新'));
  },tr('保存'));
  draw();
}
function organizeManualCategories(ids:string[]){const categories=state.categories.filter(category=>category.manual);if(!categories.length){toast(tr('请先新建一个手动分类'));return;}const selectedItems=ids.map(id=>clipsByID.get(id)).filter((item):item is Clip=>!!item);modal(tr('整理到手动分类'),tr`<p class="field-help">${tr('勾选后会将所选记录归入分类；取消勾选会移出该分类。')}</p><div class="manual-category-list">${categories.map(category=>{const checked=selectedItems.length>0&&selectedItems.every(item=>item.manualCategories?.includes(category.id));return `<label><input type="checkbox" data-manual-category="${category.id}" ${checked?'checked':''}><span class="category-mark" style="--category-color:${category.color}">${categoryGlyph(category.icon)}</span><span>${esc(category.name)}</span></label>`;}).join('')}</div>`,async()=>{for(const category of categories)await api.setManualCategory(ids,category.id,document.querySelector<HTMLInputElement>(`[data-manual-category="${category.id}"]`)!.checked);await refresh();toast(tr('分类已更新'));},tr('保存分类'));}
function orderedCategories(){return state.categories.filter(c=>!c.parentId).flatMap(c=>[c,...state.categories.filter(child=>child.parentId===c.id)]);}
let categoryCounts:Record<string,number>={},categoryCountRequest=0;
async function refreshCategoryCounts(){const request=++categoryCountRequest;if(!state.categories.length){categoryCounts={};return;}try{const counts=await api.categoryCounts();if(request!==categoryCountRequest||!counts)return;categoryCounts=counts;for(const category of state.categories){const button=document.querySelector<HTMLElement>(`#categories [data-category="${category.id}"]`),count=counts[category.id];if(button&&Number.isInteger(count)&&count>=0){button.querySelector('small')!.textContent=formatNumber(count);button.title=category.name+' · '+formatNumber(count);}}}catch(error){if(request===categoryCountRequest)toast(error);}}
function categoryNavigation(){const node=q('categories');if(!node)return;keyedMarkup(node,[{key:':heading',html:`<div class="category-heading"><span>${tr('自定义分类')}</span><div class="category-heading-actions">${state.categories.length?ib('manage-categories',tr('管理分类'),'more'):''}${ib('add-category',tr('新建分类'),'plus')}</div></div>`},...orderedCategories().map(c=>({key:c.id,html:`<button class="nav-item category-nav-item ${c.parentId?'sub-category':''} ${page==='category:'+c.id?'selected':''}" data-category="${c.id}" aria-label="${esc(c.name)}" title="${esc(c.name)}" ${page==='category:'+c.id?'aria-current="page"':''}><span class="category-mark" style="--category-color:${c.color}">${categoryGlyph(c.icon)}</span><span class="category-name">${esc(c.name)}</span><small>${categoryCounts[c.id]===undefined?'':formatNumber(categoryCounts[c.id])}</small></button>`}))]);hydrateCategoryGlyphs(node);on('add-category',()=>advanced.category());on('manage-categories',manageCategories);node.querySelectorAll<HTMLElement>('[data-category]').forEach(b=>b.onclick=()=>{resetClipFilters();page='category:'+b.dataset.category;selected='';query='';checked.clear();matches=null;render();void runSearch().catch(toast);});void refreshCategoryCounts();}
function headingActions(){
 if(page==='replies')return button('new-reply',tr('新建回复'),'plus','primary')+ib('batch-mode',batchMode?tr('退出批量选择'):tr('批量选择'),batchMode?'close':'check',batchMode);
 if(page==='stack')return ib('stack-rules',tr('堆栈规则'),'settings')+ib('stack-batch',tr('批量入栈'),'plus')+ib('stack-reverse',tr('反转顺序'),'undo')+button('stack-running',state.stack.running?tr('停止自动入栈'):tr('开始自动入栈'),state.stack.running?'pause':'play')+button('paste-next',tr('粘贴下一项'),'enter','primary');
 const menuAction=(id:string,label:string,glyph:string)=>`<button id="${id}" type="button" role="menuitem">${ico(glyph)}<span>${label}</span></button>`;
 const extra=page==='shelf'?menuAction('open-shelf',tr('浮动窗口'),'monitor'):categoryId()?menuAction('edit-category',tr('编辑分类'),'edit')+menuAction('remove-category',tr('删除分类'),'trash'):'';
 const menu=`<div class="collection-action-menu">${ib('collection-more-toggle',tr('更多操作'),'more')}<div id="collection-more-menu" class="collection-more-menu" role="menu" aria-label="${tr('更多操作')}" aria-hidden="true" hidden>${menuAction('open-quick-panel',tr('快捷面板'),'clipboard')}${extra}${page==='history'?`<div role="separator"></div>${menuAction('clear-history-main',tr('清空历史'),'trash')}`:''}</div></div>`;
 return (page==='shelf'?button('add-files',tr('添加文件'),'plus','primary'):'')+ib('batch-mode',batchMode?tr('退出批量选择'):tr('批量选择'),batchMode?'close':'check',batchMode)+ib('undo-delete',tr('撤销删除'),'undo')+menu;
}
function bindAdvanced(){
  on('clear-history-main',()=>confirm(tr('清空历史？'),tr(HISTORY_CLEAR_DETAIL),async()=>{await api.clear();selected='';checked.clear();matches=null;await refresh();},true));
  on('stack-rules',()=>stackPanel.rules());on('stack-batch',()=>stackPanel.batch());on('stack-reverse',()=>api.reverseStack());on('stack-running',()=>api.setStackRunning(!state.stack.running));
  on('open-quick-panel',()=>api.showQuick());on('open-shelf',()=>api.showShelf());on('add-files',()=>api.addFiles());on('batch-mode',()=>{batchMode=!batchMode;checked.clear();renderCollection();});
  on('edit-category',()=>advanced.category(state.categories.find(c=>c.id===categoryId())));on('remove-category',()=>confirm(tr('删除分类？'),tr('只删除分类规则，历史内容保留。'),async()=>{await api.removeCategory(categoryId()!);page='history';matches=null;await refresh();render();}));
  const drop=q('shelf-drop');if(drop){const area=q('content');area.ondragover=e=>{if(acceptsDrop(e.dataTransfer)){e.preventDefault();e.dataTransfer!.dropEffect='copy';drop.classList.add('dragging');}};area.ondragleave=e=>{if(!area.contains(e.relatedTarget as Node))drop.classList.remove('dragging');};area.ondrop=e=>{e.preventDefault();drop.classList.remove('dragging');let pending:Promise<boolean>|null=null;try{pending=e.dataTransfer&&importDroppedImage(e.dataTransfer,api);}catch(error){toast(error);return;}if(pending)void pending.then(imported=>{if(imported)toast(tr('已添加到拖拽容器'));}).catch(toast);};}else{q('content').ondragover=null;q('content').ondrop=null;q('content').ondragleave=null;}
}
