  const meter=q('storage-meter');
  if(!meter)return;
  const usage=storageUsage();
  meter.dataset.level=usage.level;
  const amount=meter.querySelector<HTMLElement>('#storage-bytes');
  const percent=meter.querySelector<HTMLElement>('#storage-percent');
  const bar=meter.querySelector<HTMLElement>('#storage-progress');
  const notice=meter.querySelector<HTMLElement>('#storage-notice');
  if(!amount||!percent||!bar||!notice)return;
  amount.textContent=bytes(state.bytes)+' / '+bytes(usage.maximum);
  percent.textContent=usage.percent+'%';
  bar.style.width=Math.min(100,usage.ratio*100)+'%';
  bar.parentElement?.setAttribute('aria-valuenow',String(Math.min(100,usage.percent)));
