document.addEventListener('keydown',e=>{
  if(e.isComposing||e.defaultPrevented)return;if(document.querySelector('dialog[open]'))return;const target=e.target as HTMLElement,editing=target.matches('input,textarea,select');
  if(e.key==='Escape'){if(document.querySelector('.reference-popover:not([hidden])'))return;e.preventDefault();if(filterPopoverOpen){setFilterPopover(false);q<HTMLButtonElement>('advanced-filter-toggle').focus();return;}void api.hide();return;}
  if(target.closest('.text-reader'))return;
  if(e.ctrlKey&&e.key.toLowerCase()==='f'){e.preventDefault();(document.getElementById('reference-search')||document.getElementById('search'))?.focus();return;}
  if(target.closest('#toast')||(!editing&&target.closest('button,summary,[role=combobox]')&&!target.closest('.clip-row')))return;
  if(['settings','text-tools','capture-tools','ai','scripts','uri','sync','web','symbols','cheats'].includes(page))return;
  if(e.ctrlKey&&e.key.toLowerCase()==='z'&&!editing){e.preventDefault();void api.undo().catch(toast);return;}
  if(editing&&target.id!=='search')return;
  if(e.key==='Enter'){e.preventDefault();void useSelected(!e.ctrlKey).catch(toast);}
  if(['ArrowDown','ArrowUp'].includes(e.key)&&page!=='replies'){e.preventDefault();const fromRow=!!target.closest('.clip-row'),i=page==='stack'?visibleQueueIndices.indexOf(selectedQueueIndex):visible.findIndex(c=>c.id===selected),index=cardNavigation(i,visible.length,1,'vertical',e.key),next=visible[index];if(next){if(index>=limit){limit=Math.ceil((index+1)/100)*100;renderCollection();}selectRow(next.id,visibleQueueIndices[index]??-1);const row=document.querySelector<HTMLElement>(`[data-id="${selected}"]${page==='stack'?`[data-queue-index="${selectedQueueIndex}"]`:''}`);row?.scrollIntoView({block:'nearest'});if(fromRow)row?.focus({preventScroll:true});}}
  if(e.key==='Delete'&&!editing&&selected&&page!=='replies'){e.preventDefault();void api.action(selected,'delete').then(()=>toast(tr('已删除记录'),true)).catch(toast);}
});
window.addEventListener('clip:language-reload',()=>sessionStorage.setItem('clip-language-navigation',JSON.stringify({page,filters:clipFilters,selected,query})));try{const saved=JSON.parse(sessionStorage.getItem('clip-language-navigation')||'null');sessionStorage.removeItem('clip-language-navigation');if(saved&&typeof saved.page==='string'){page=saved.page==='data'?'settings':saved.page==='tools'?'ai':saved.page;clipFilters=normalizeClipFilters(saved.filters||{kinds:saved.kind&&saved.kind!=='all'?[saved.kind]:[],sources:saved.sourceApp?[saved.sourceApp]:[]});selected=saved.selected||'';query=saved.query||'';}}catch{}
q<HTMLDialogElement>('dialog').addEventListener('close',()=>setTimeout(()=>checkExternal(),0));
let refreshScheduled:ReturnType<typeof setTimeout>|undefined,refreshPending=false;
function scheduleRefresh(){refreshPending=true;if(!state||!isWindowVisible()||refreshScheduled)return;refreshScheduled=setTimeout(()=>{refreshScheduled=undefined;if(!isWindowVisible())return;refreshPending=false;void refresh().catch(toast);},32);}
setupWindowVisibility();onWindowVisibility(shown=>{if(!state)return;if(shown)scheduleRefresh();else{clearTimeout(refreshScheduled);refreshScheduled=undefined;clearTimeout(searchTimer);refreshToken++;searchRevision++;closeControls();suspendDetail();}});
api.onChange(scheduleRefresh);api.onNotice(toast);api.onChatSettings?.(()=>{page='text-tools';tools.setTab('ai');render();});
async function start(){state=await api.state();clipsByID=new Map(state.clips.map(c=>[c.id,c]));shell();render();checkExternal();if(refreshPending)scheduleRefresh();}
void start().catch(e=>{q('app').textContent=tr('Clip 加载失败：')+String(e);});
